#include <iostream>
#include <memory>
using namespace std;

struct Fish {
    int n;
    Fish(int v) : n(v) { cout << "领到 " << n << endl; }
    ~Fish() { cout << "还回 " << n << endl; }
};

void work(int v, bool early) {
    unique_ptr<Fish> p = make_unique<Fish>(v);
    if (early) {
        return;
    }
    cout << "用 " << p->n << endl;
}

int main() {
    int x = 0;
    cin >> x;

    work(x, false);
    cout << "---" << endl;
    work(x, true);
    cout << "收工" << endl;
    return 0;
}
